/* ==========================================================================
   The Flavour Lounge - Special Deals Page Styles
   Reuses shared CSS variables from css/style.css
   ========================================================================== */

.deals-subtitle {
    max-width: 38rem;
}

/* Category Filter Pills */
.filter-btn {
    background-color: var(--color-white);
    color: var(--color-maroon);
    border: 2px solid var(--color-cream-dark);
    border-radius: 50rem;
    padding: 0.45rem 1.2rem;
    font-weight: 600;
    font-size: 0.92rem;
    transition: all var(--transition-base);
}

.filter-btn:hover,
.filter-btn:focus-visible,
.filter-btn.active {
    background-color: var(--color-orange);
    border-color: var(--color-orange);
    color: var(--color-white);
}

/* Deal Cards extending shared .flavour-card look */
.deal-card {
    background-color: var(--color-white);
    border: 1px solid color-mix(in srgb, var(--color-maroon) 12%, transparent);
    border-radius: var(--radius-lg);
    overflow: hidden;
    box-shadow: var(--shadow-soft);
    transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.deal-card:hover {
    transform: translateY(-6px);
    box-shadow: var(--shadow-card);
}

.deal-img-wrapper {
    position: relative;
    background-color: var(--color-cream-dark);
}

.deal-img {
    width: 100%;
    height: 200px;
    object-fit: cover;
    display: block;
}

/* Discount Percentage Badge */
.discount-badge {
    position: absolute;
    top: 12px;
    right: 12px;
    background-color: var(--color-orange);
